declare p jsonb := '[{"book":"ulisse","id":"america","collection":"cited","name":"Americas","noteHash":"dae0590e001380267e5264352d7b9d92","positionSource":"a8d1cf97505410249f942c6baed787e20af8a3cfc13ea3ef1ad526633487b566","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"America figures in accounts of emigration and news arriving in Dublin.","it":"L’America compare nei racconti di emigrazione e nelle notizie che arrivano a Dublino.","fr":"L’Amérique apparaît dans les récits d’émigration et les nouvelles arrivant à Dublin.","es":"América aparece en relatos de emigración y noticias que llegan a Dublín."}}},{"book":"ulisse","id":"amsterdam","collection":"cited","name":"Amsterdam","noteHash":"dae0590e001380267e5264352d7b9d92","positionSource":"252d6a98fb85e691bb6f7e446b0baa65e0c673916756b9c6a6fbc743648a4c41","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Amsterdam is mentioned as the home of the composer Jan Pieterszoon Sweelinck.","it":"Amsterdam è citata come città del compositore Jan Pieterszoon Sweelinck.","fr":"Amsterdam est citée comme ville du compositeur Jan Pieterszoon Sweelinck.","es":"Ámsterdam se menciona como ciudad del compositor Jan Pieterszoon Sweelinck."}}},{"book":"ulisse","id":"austria","collection":"cited","name":"Austria","noteHash":"dae0590e001380267e5264352d7b9d92","positionSource":"394d399d4aa7af5e415a8ff62a0d122658da3c8dba3e0303a0cbb0593a72662a","narrativeSource":null,"description":{"status":"reviewed","reviewedAt":"2026-11-03","basis":"existing geographic and literary sources associated with this place","texts":{"en":"Lower Austria appears in Mr Deasy’s notes about the emperor’s horses.","it":"La Bassa Austria compare negli appunti del signor Deasy sui cavalli dell’imperatore.","fr":"La Basse